19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	const ITEM_BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	};
29	
30	const quotePremium = (items: Item[]): number => {
31	  const policyBasePremium = items.reduce(
32	    (sum, item) => sum + ITEM_BASE_PREMIUMS[item.type],
33	    0,
34	  );
35	  return Math.ceil(
36	    policyBasePremium +
37	      policyBasePremium * FIRST_INSURANCE_SURCHARGE +
38	      PROCESSING_FEE,
39	  );
40	};
41	
42	export const runScenario = (scenario: Scenario): ScenarioResults => {
43	  return {
44	    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
45	  };
46	};
