const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const sumItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + ITEM_BASE_PREMIUMS[item.type], 0);

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = sumItemBasePremiums(items);
  return roundInMHPCOsFavour(
    policyBasePremium +
      policyBasePremium * FIRST_INSURANCE_SURCHARGE +
      PROCESSING_FEE,
  );
};
